func:
// Recebe o JSON publicado pelo app17-11 em FIAPIoT/motor/multiclasse.
// No MQTT-in em datatype "json" o payload ja chega como objeto; protegemos
// mesmo assim contra string.
let p = msg.payload;
if (typeof p === "string") {
    try { p = JSON.parse(p); }
    catch (e) { node.error("Payload nao e JSON valido", msg); return null; }
}

// label vem da SEQUENCIA CICLICA do proprio ESP32 (avancada pelo botao 18).
const label = p.label || "desconhecido";
// rodada identifica a VOLTA completa pela sequencia -- e o group do
// LeaveOneGroupOut no notebook 2.6, por isso vira tag (como no app17-6), nao field.
const rodada = String(p.rodada != null ? p.rodada : "00");

// As 8 features (mean_*/std_* dos 3 eixos + std_mag + p2p_mag) + janela
// (indice dentro da rodada) + ts_epoch_ms (NTP, so para referencia -- o ponto
// usa o horario de recepcao, igual ao app17-6).
const fields = {
    janela:      Number(p.janela),
    ts_epoch_ms: Number(p.ts_epoch_ms) || 0,
    mean_ax:     Number(p.mean_ax),
    mean_ay:     Number(p.mean_ay),
    mean_az:     Number(p.mean_az),
    std_ax:      Number(p.std_ax),
    std_ay:      Number(p.std_ay),
    std_az:      Number(p.std_az),
    std_mag:     Number(p.std_mag),
    p2p_mag:     Number(p.p2p_mag)
};

// label e rodada como TAGS: e o que o notebook 2.6 usa pra agrupar
// (groupby label/rodada) e pro LeaveOneGroupOut por rodada.
const tags = {
    label:  label,
    rodada: rodada,
    device: p.device || "esp32"
};

node.status({ fill: "green", shape: "dot",
    text: label + " r" + rodada + " | std_mag=" + (isFinite(fields.std_mag) ? fields.std_mag.toFixed(3) : "?") });

// node-red-contrib-influxdb: payload = [fields, tags]
msg.payload = [fields, tags];
return msg;
